insert into flow.definitions (id, key, name, description) values
  ('df839efb-fe98-56f0-9fe2-a8b9d3d27de8', 'prueba_alojamiento', 'Prueba del alojamiento (finde)', 'Los 20 pasos de la prueba del alojamiento tipo barra, guiados sobre ven.ikisai.com y la Recepción de Booking. Dos móviles: visitante (A) y recepción (B).');
insert into flow.definition_versions (id, definition_id, version, status) values ('a68cefcc-8d03-5cb6-ab23-4000cd173d45', 'df839efb-fe98-56f0-9fe2-a8b9d3d27de8', 1, 'draft');
insert into flow.definition_stages (id, version_id, position, kind, title, explain, target_app, target_anchor) values
  ('1c0302dc-d330-5cd4-8196-8e7f700eb6d6', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 1, 'handoff', '1. Alta del evento', 'Móvil B: en Reservas, da de alta el evento de prueba «Jornadas abiertas» (fechas del finde, precio por noche, «Guardar la cama» 2 h).', 'booking', 'booking' || '.reservas.alta.guardar'),
  ('c086b9d7-eff0-51b7-bca2-44ee4f89b476', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 2, 'handoff', '1. Confirmar el evento', 'Móvil B: abre esa reserva y «Confirmar»: crea el evento y su código público. Apúntalo en el paso siguiente.', 'booking', 'booking' || '.reserva.acciones.confirmar'),
  ('983d8d59-81cc-5caa-a80d-5dd0fbd8e014', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 3, 'record', '1. ¿Ha pasado?', 'El evento sale en ven.ikisai.com, en la portada de eventos abiertos.', null, null),
  ('814d61ab-314b-5dda-b940-b38cd1b312f3', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 4, 'handoff', '2. Camas colocadas', 'Móvil B: en «Plano y ficha» de una habitación con 2 o 3 camas, «Monta el dormitorio» y coloca las camas. Mira el plano de Recursos en Central.', 'booking', null),
  ('3e8551f2-23e4-56c3-9164-a697a3aa05c9', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 5, 'record', '2. ¿Ha pasado?', 'En el plano de Central, las camas salen dentro de su habitación.', null, null),
  ('157a77e9-d47b-538d-b990-7de05d5b4b8d', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 6, 'handoff', '3. Entrar sin sesión', 'Móvil A: abre el QR del evento (o ven.ikisai.com/e/CÓDIGO).', 'guests', 'guests' || '.visitante.pestana.alojate'),
  ('0c490cf8-e5a2-526a-855d-1e63a9caf1f1', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 7, 'record', '3. ¿Ha pasado?', 'Dos pestañas, «El evento» y «Alójate aquí»; sin iniciar sesión; el móvil queda como visitante.', null, null),
  ('a11f27d6-499d-580b-addd-c7f584b36d13', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 8, 'record', '4. ¿Ha pasado?', 'En otro móvil, abre ven.ikisai.com y entra al evento desde la portada, sin el QR. Debería pasar: Ves el evento, pero no «Alójate aquí».', null, null),
  ('1eaf0530-9741-54e0-a8a7-67e81de3e9d8', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 9, 'record', '5. ¿Ha pasado?', 'Móvil A: abre flow.ikisai.com/carta y toca «Alójate aquí». Debería pasar: Vuelve a ven.ikisai.com, misma pestaña y misma identidad, sin pedir nada.', null, null),
  ('06eab929-3844-5482-8ddc-bdcf32901def', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 10, 'handoff', '6. Noches', 'Móvil A: en «Alójate aquí» → «Tus noches», elige llegada y salida (2 noches).', 'guests', 'guests' || '.visitante.alojate.llegada'),
  ('150eebef-684c-5d8b-a9b7-fe1ea911690b', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 11, 'record', '6. ¿Ha pasado?', '«X la noche · Y en total (2 noches)».', null, null),
  ('04294267-a5de-5a03-a853-ba33e4291b9e', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 12, 'record', '7. ¿Ha pasado?', 'Móvil A: mira «Tu cama». Debería pasar: Marcado «Asignadme una»; debajo, las camas libres todas esas noches por habitación, con su nombre público; nunca el nombre de nadie.', null, null),
  ('862a54d2-b67b-557b-9dff-b0db1da24e97', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 13, 'handoff', '8. Cama, en el plano', 'Móvil A: «Ver las camas en el plano» y toca una cama libre.', 'guests', 'guests' || '.visitante.alojate.plano'),
  ('c7d42655-7956-57be-bcef-ba9da0cf5468', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 14, 'record', '8. ¿Ha pasado?', 'El plano con las libres en verde y el resto apagadas y sin nombre; tocar una marca su opción en la lista.', null, null),
  ('e9cbaa66-74e9-5f3b-a864-7701d707584e', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 15, 'handoff', '9. Tus datos (borrador)', 'Móvil A: en «Tus datos», escribe solo nombre y primer apellido (inventados).', 'guests', 'guests' || '.visitante.alojate.viajero.first_name'),
  ('1202980a-f585-55e7-a530-4e88f0e49e35', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 16, 'record', '9. ¿Ha pasado?', 'Dice que es un borrador y que el documento no hace falta ahora; solo el nombre es obligatorio.', null, null),
  ('59b93b9a-e7c1-5023-b4c3-bae40b4f41d8', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 17, 'handoff', '10. Ir a pagar', 'Móvil A: «Ir a pagar».', 'guests', 'guests' || '.visitante.alojate.pagar'),
  ('d9d009fc-bf7f-5d59-bdd0-cda5e1ffe5f8', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 18, 'record', '10. ¿Ha pasado?', '«Tu número» en grande; «Ve a recepción y di tu número para pagar.»; «Tu cama está guardada hasta el …»; la cama o «te asignan cama al pagar».', null, null),
  ('80f6c9b7-7a3f-512e-8e0e-faea17757bde', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 19, 'record', '11. ¿Ha pasado?', 'Móvil A: mira debajo del número. Debería pasar: «Para dormir te faltará: …» con el documento y los demás campos, y «Completar mis datos».', null, null),
  ('403cc91a-709a-55c1-8ac0-7f04c96ca40b', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 20, 'handoff', '12. Completar desde el móvil', 'Móvil A: «Completar mis datos» → tipo y número de documento y fecha de nacimiento (inventados) → «Guardar».', 'guests', 'guests' || '.visitante.alojate.datos'),
  ('f15f8592-60e3-5c51-b017-b2edd5fb2950', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 21, 'record', '12. ¿Ha pasado?', '«Guardado.» y la lista de lo que falta se acorta.', null, null),
  ('3011726d-5b86-5018-9ba4-dd273e1fc887', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 22, 'handoff', '13. Guarda tu acceso (opcional)', 'Móvil A: al pie, «Guarda tu acceso» → tu correo → código → «Guardar mi acceso».', 'guests', 'guests' || '.visitante.acceso'),
  ('fc2b1e5a-c947-5075-b0d9-03b15ceef543', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 23, 'record', '13. ¿Ha pasado?', '«Tu acceso queda guardado»; en otro móvil, con el mismo correo, recuperas el evento y tu número.', null, null),
  ('e85958de-3e8c-5659-a311-a22907198e0f', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 24, 'handoff', '14. Buscar el número', 'Móvil B (Booking, Recepción): busca el número del paso 10.', 'booking', 'booking' || '.recepcion.buscar'),
  ('e2b00cb2-709e-59e5-bb39-9e46ac33e502', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 25, 'record', '14. ¿Ha pasado?', 'La solicitud en «Por pagar» con noches, cama retenida, total y lo que falta; ves los datos del paso 12.', null, null),
  ('4681085a-1722-52ec-8a67-dbcc4e512c98', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 26, 'handoff', '15. Cobrar y alojar', 'Móvil B: completa lo que falte → «Cobrar y alojar» → Bizum o efectivo.', 'booking', 'booking' || '.recepcion.cobrar'),
  ('f3c96a9b-41b1-5e6e-ae60-4ea810c9fe3b', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 27, 'record', '15. ¿Ha pasado?', 'Ficha y cama con fechas; cobro pagado; un apunte en Finance; repetir no duplica.', null, null),
  ('f69e8c4b-ce2a-5e88-bb57-705a88a2f575', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 28, 'record', '16. ¿Ha pasado?', 'Móvil A: espera unos 20 s o recarga. Debería pasar: «Esta noche duermes en …» con habitación y cama; el número y «Ve a recepción» desaparecen.', null, null),
  ('c7131437-a996-5b3d-9393-9ea12f1ca440', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 29, 'handoff', '17. Llega', 'Móvil B: en Recepción, en los huéspedes, «Llega».', 'booking', 'booking' || '.recepcion.llega'),
  ('9afcae9b-6620-51f6-b966-cde6e0ba9608', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 30, 'record', '17. ¿Ha pasado?', 'En el móvil A sigue «Esta noche duermes en …»; en Booking, alojado.', null, null),
  ('2d7df440-5e92-5db0-a524-e089a3679ad3', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 31, 'record', '18. ¿Ha pasado?', 'En otro móvil por el QR, «Alójate aquí» con las mismas noches. Debería pasar: Esa cama no sale libre, ni en la lista ni en el plano.', null, null),
  ('4916391d-011d-541b-ac58-c8d65781fe82', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 32, 'handoff', '19. Sale', 'Móvil B: en Recepción, «Sale».', 'booking', 'booking' || '.recepcion.sale'),
  ('1e891abf-481b-5d36-8dd5-0479c5a3f9dc', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 33, 'record', '19. ¿Ha pasado?', 'La cama queda libre esa noche; en Tasks, la limpieza; «Deshacer» la devuelve si nadie la ha ocupado.', null, null),
  ('34908ca7-4e2a-5cd6-b807-4ba32dbe3b45', 'a68cefcc-8d03-5cb6-ab23-4000cd173d45', 34, 'record', '20. ¿Ha pasado?', 'Comprueba plano, pago (un cobro, su apunte, Central bajó en uno) y datos (borrador + recepción; nada a otros visitantes; documento solo para dormir). Debería pasar: Todo cuadra (caducidad, opcional: sin pasar por recepción, a las 2 h la cama vuelve a estar libre).', null, null);
